//! bimcraft-cli: the command line of a BIM modeler.

#[macro_use]
pub mod json;
pub mod arch;
pub mod catalog;
pub mod check;
pub mod cloud;
pub mod commands;
pub mod edit;
pub mod deflate;
pub mod ifc;
pub mod inflate;
pub mod inspect;
