use std::process::exit;

pub const VERSION: &str = "0.10.0";

fn usage_exit(prefix: Option<String>) -> ! {
    if let Some(p) = prefix {
        eprint!("{}\n\n", p);
    }
    eprint!("{}", catalog::USAGE);
    exit(1);
}

enum Action {
    Open(String),
    Sample,
    Highrise,
    Cmd(String),
    Script(String),
    Save(String),
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.is_empty() {
        usage_exit(None);
    }
    match args[0].as_str() {
        "--version" | "-V" if args.len() == 1 => {
            println!("bimcraft-cli {}", VERSION);
        }
        "commands" if args.len() == 1 => {
            let v = json::parse(catalog::CATALOG).unwrap();
            println!("{}", v.to_pretty());
        }
        "info" if args.len() == 2 => cmd_info(&args[1]),
        "convert" if args.len() == 3 => cmd_convert(&args[1], &args[2]),
        "run" => cmd_run(&args[1..]),
        "mcp" => commands::mcp_main(&args[1..]),
        _ => usage_exit(None),
    }
}

fn cmd_run(args: &[String]) {
    let mut actions = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "--sample" => actions.push(Action::Sample),
            "--highrise" => actions.push(Action::Highrise),
            "--cmd" | "--script" | "--save" => {
                if i + 1 >= args.len() {
                    usage_exit(Some(format!("{} needs a value", a)));
                }
                let v = args[i + 1].clone();
                i += 1;
                actions.push(match a.as_str() {
                    "--cmd" => Action::Cmd(v),
                    "--script" => Action::Script(v),
                    _ => Action::Save(v),
                });
            }
            _ if a.starts_with("--") => usage_exit(Some(format!("unknown option `{}`", a))),
            _ => actions.push(Action::Open(a.clone())),
        }
        i += 1;
    }
    let mut s = session::Session::new();
    for act in actions {
        match act {
            Action::Open(path) => match commands::open_path(&mut s, &path) {
                Ok(v) => println!("{}", v.sorted().to_compact()),
                Err(e) => {
                    // a Revit import's error is a whole message, the path first
                    if rvt::is_revit_path(&path) {
                        eprintln!("{}", e);
                    } else {
                        eprintln!("open: {}", e);
                    }
                    exit(1);
                }
            },
            Action::Sample => {
                if let Err(e) = commands::build_sample(&mut s) {
                    eprintln!("{}", e);
                    exit(1);
                }
            }
            Action::Highrise => match commands::build_highrise(&mut s, 20) {
                Ok(v) => println!("{}", v.sorted().to_compact()),
                Err(e) => {
                    eprintln!("{}", e);
                    exit(1);
                }
            },
            Action::Cmd(text) => run_script_text(&mut s, &text),
            Action::Script(path) => match std::fs::read(&path) {
                Ok(bytes) => {
                    let text = String::from_utf8_lossy(&bytes).to_string();
                    run_script_text(&mut s, &text)
                }
                Err(e) => {
                    eprintln!("{}: {}", path, commands::io_err(&e));
                    exit(1);
                }
            },
            Action::Save(path) => {
                let p = json::Value::Obj({
                    let mut m = json::Map::new();
                    m.insert("path", json::Value::s(&path));
                    m
                });
                match s.execute("save", &p) {
                    Ok(v) => println!("{}", v.sorted().to_compact()),
                    Err(e) => {
                        eprintln!("save: {}", e);
                        exit(1);
                    }
                }
            }
        }
    }
}

fn run_script_text(s: &mut session::Session, text: &str) {
    let lines = match script::parse(text) {
        Ok(l) => l,
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    };
    // a script's replies are printed once all of it has gone through
    let mut out = String::new();
    for l in lines {
        match s.execute(&l.id, &l.params) {
            Ok(v) => {
                out.push_str(&v.sorted().to_compact());
                out.push('\n');
            }
            Err(e) => {
                eprintln!("line {} ({}): {}", l.line, l.id, e);
                exit(1);
            }
        }
    }
    print!("{}", out);
}

fn cmd_info(path: &str) {
    match commands::info(path) {
        Ok(v) => println!("{}", v.sorted().to_pretty()),
        Err(e) => {
            eprintln!("{}", e);
            exit(1);
        }
    }
}

fn cmd_convert(input: &str, output: &str) {
    let mut s = session::Session::new();
    match commands::open_path(&mut s, input) {
        Ok(_) => {}
        Err(e) => {
            // a Revit import's error is a whole message, the path first
            if rvt::is_revit_path(input) {
                eprintln!("{}", e);
            } else {
                eprintln!("open: {}", e);
            }
            exit(1);
        }
    }
    let mut m = json::Map::new();
    m.insert("path", json::Value::s(output));
    match s.execute("save", &json::Value::Obj(m)) {
        Ok(v) => println!("{}", v.sorted().to_compact()),
        Err(e) => {
            eprintln!("save: {}", e);
            exit(1);
        }
    }
}
//! The commands: their registry, dispatch, and the project-level ones.

pub mod basic;
pub mod params;

use crate::json::Value;
use crate::session::Session;
use std::sync::OnceLock;

pub struct CmdInfo {
    pub id: String,
    pub label: String,
    pub aliases: Vec<String>,
}

fn registry() -> &'static Vec<CmdInfo> {
    static REG: OnceLock<Vec<CmdInfo>> = OnceLock::new();
    REG.get_or_init(|| {
        let v = crate::json::parse(crate::catalog::CATALOG).unwrap();
        v.as_arr()
            .unwrap()
            .iter()
            .map(|c| CmdInfo {
                id: c.get("id").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                label: c.get("label").and_then(|x| x.as_str()).unwrap_or("").to_string(),
                aliases: c
                    .get("aliases")
                    .and_then(|x| x.as_arr())
                    .map(|a| a.iter().filter_map(|s| s.as_str().map(|s| s.to_string())).collect())
                    .unwrap_or_default(),
            })
            .collect()
    })
}

/// A command's id and label, from its id or one of its aliases, in any case.
pub fn resolve(id: &str) -> Option<(String, String)> {
    let reg = registry();
    let low = id.to_lowercase();
    if let Some(c) = reg.iter().find(|c| c.id.to_lowercase() == low) {
        return Some((c.id.clone(), c.label.clone()));
    }
    if let Some(c) = reg.iter().find(|c| c.aliases.iter().any(|a| a.to_lowercase() == low)) {
        return Some((c.id.clone(), c.label.clone()));
    }
    None
}

pub fn label_of(cid: &str) -> String {
    registry().iter().find(|c| c.id == cid).map(|c| c.label.clone()).unwrap_or_default()
}

/// Commands that only read the model (no undo step, no check).
pub fn changes_model(cid: &str) -> bool {
    !matches!(
        cid,
        "inspect"
            | "elements"
            | "render"
            | "measure"
            | "library"
            | "select_by_id"
            | "ids_of"
            | "filter_selection"
            | "sketch"
            | "save"
            | "autosave"
            | "circuit"
            | "conduit_fill"
            | "drain_size"
            | "vent_size"
            | "hydrant_size"
            | "load_points"
            | "water_size"
            | "storm_size"
            | "export_fill_patterns"
            | "cad_query"
    )
}

/// Undo and redo move the history themselves; opening a project starts a new one.
pub fn is_history_cmd(cid: &str) -> bool {
    matches!(cid, "undo" | "redo" | "new" | "open" | "recover" | "highrise")
}

pub fn always_step(cid: &str) -> bool {
    // some commands make an undo step even when the model is unchanged; each module owns its own
    crate::media::always_step(cid) || crate::styles::step_anyway(cid)
}

pub fn run(s: &mut Session, cid: &str, p: &Value) -> Result<Value, String> {
    if s.read_only && changes_model(cid) && !matches!(cid, "save") {
        return Err(format!("{}: this project is open read-only, so it can't be changed", cid));
    }
    if let Some(r) = crate::cloud::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::media::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::styles::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::arch::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::structure::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::views::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::edit::dispatch(s, cid, p) {
        return r;
    }
    if let Some(r) = crate::readers::dispatch(s, cid, p) {
        return r;
    }
    basic::run(s, cid, p)
}

pub fn io_err(e: &std::io::Error) -> String {
    e.to_string()
}

pub fn open_path(s: &mut Session, path: &str) -> Result<Value, String> {
    basic::open_path(s, path)
}

pub fn info(path: &str) -> Result<Value, String> {
    basic::info(path)
}

pub fn build_sample(s: &mut Session) -> Result<(), String> {
    basic::build_sample(s)
}

pub fn build_highrise(s: &mut Session, storeys: u64) -> Result<Value, String> {
    basic::build_highrise(s, storeys)
}

pub fn mcp_main(args: &[String]) {
    crate::mcp::main(args)
}

//! `bimcraft-cli`: BIMCraft from the command line. Scripts, conversion, and an MCP server for
//! agents, all through the same commands.

mod mcp;
mod revit;
mod window;

use std::io::Write;
use std::process::ExitCode;

use bimcraft_core::cad::DwgReader;
use bimcraft_core::engine::{Session, catalog};
use bimcraft_core::sample::SAMPLE;
use serde_json::{Value, json};

const USAGE: &str = "USAGE:
  bimcraft-cli run [FILE] [--sample | --highrise] [--cmd 'ID {json}']… [--script FILE]… [--save PATH]…
      Open FILE (a .bimcraft project, or an .ifc or Revit .rvt file to import) or start empty, then in order: build the sample house, run
      commands and scripts (one `ID {json}` per line), save. --save writes by extension:
      .bimcraft (the project), .ifc (IFC4), .glb (the 3D view's scene as glTF), .svg or .png (the lowest level's plan).
      --highrise builds an original 20-storey performance sample (about 10,000 elements).
  bimcraft-cli info FILE         levels, element counts, types and warnings of a project or an IFC file; of a Revit .rvt or
                                 .rfa file, its release, last save, levels and element counts by category
  bimcraft-cli convert IN OUT    a project, an IFC file or a Revit .rvt file to .ifc, .glb, .svg, .png or .bimcraft
  bimcraft-cli commands          every command and its parameters
  bimcraft-cli mcp [--read-only] [FILE | --connect [PORT]]
                                 an MCP server on stdio, for agents: on a headless project of its own (FILE, opened first, or an
                                 empty one), or with --connect on the project open in a window whose control port is open
                                 (`bimcraft --control PORT` or File > Settings > Agents; without PORT, the last one). With
                                 --read-only the agent may read the project, never change it or write over its file
  bimcraft-cli --version         the release";

fn print(out: &mut impl Write, v: &Value) -> Result<(), String> {
    writeln!(out, "{v}").map_err(|e| format!("stdout: {e}"))
}

fn print_pretty(out: &mut impl Write, v: &Value) -> Result<(), String> {
    writeln!(out, "{}", serde_json::to_string_pretty(v).unwrap_or_default()).map_err(|e| format!("stdout: {e}"))
}

fn cli(args: &[String], out: &mut impl Write) -> Result<(), String> {
    let mut s = Session::new();
    s.dwg = dwg_reader();
    match args {
        [cmd, rest @ ..] if cmd == "run" => {
            let mut rest = rest.iter();
            while let Some(arg) = rest.next() {
                let mut value = || rest.next().ok_or_else(|| format!("{arg} needs a value\n\n{USAGE}"));
                let results = match arg.as_str() {
                    "--sample" => s.script(SAMPLE).map(|_| Vec::new())?,
                    "--highrise" => vec![s.execute("highrise", &json!({}))?],
                    "--cmd" => s.script(value()?)?,
                    "--script" => {
                        let path = value()?;
                        s.script(&std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?)?
                    }
                    "--save" => vec![s.execute("save", &json!({ "path": value()? }))?],
                    flag if flag.starts_with("--") => return Err(format!("unknown option `{flag}`\n\n{USAGE}")),
                    file if revit::is_revit(file) => vec![revit::open(&mut s, file)?],
                    file => vec![s.execute("open", &json!({ "path": file }))?],
                };
                for r in results.iter().filter(|r| !r.is_null()) {
                    print(out, r)?;
                }
            }
            Ok(())
        }
        [cmd, file] if cmd == "info" && revit::is_revit(file) => print_pretty(out, &revit::info(file)?),
        [cmd, file] if cmd == "info" => {
            s.execute("open", &json!({ "path": file }))?;
            print_pretty(out, &s.execute("inspect", &json!({}))?)
        }
        [cmd, from, to] if cmd == "convert" => {
            if revit::is_revit(from) {
                revit::open(&mut s, from)?;
            } else {
                s.execute("open", &json!({ "path": from }))?;
            }
            print(out, &s.execute("save", &json!({ "path": to }))?)
        }
        [cmd] if cmd == "commands" => print_pretty(out, &catalog()),
        [flag] if flag == "--version" || flag == "-V" => {
            writeln!(out, "bimcraft-cli {}", env!("CARGO_PKG_VERSION")).map_err(|e| format!("stdout: {e}"))
        }
        _ => Err(USAGE.into()),
    }
}

/// What follows `mcp`.
#[derive(Debug, Default, PartialEq)]
struct McpArgs {
    /// `--connect`, with a port or without: none inside is a window, whichever the bridge file names.
    connect: Option<Option<u16>>,
    /// `--read-only`: the agent may read the project and never change it.
    read_only: bool,
    /// The project a headless server opens before it answers.
    file: Option<String>,
}

const MCP_USAGE: &str = "usage: bimcraft-cli mcp [--read-only] [FILE | --connect [PORT]]";

fn mcp_args(args: &[String]) -> Result<McpArgs, String> {
    let mut a = McpArgs::default();
    let mut rest = args.iter().peekable();
    while let Some(arg) = rest.next() {
        match arg.as_str() {
            "--read-only" => a.read_only = true,
            "--connect" if a.connect.is_none() => {
                let port = rest.next_if(|p| !p.starts_with("--"));
                a.connect = Some(port.map(|p| p.parse().map_err(|_| format!("`{p}` is not a port: a number up to 65535"))).transpose()?);
            }
            flag if flag.starts_with('-') => return Err(format!("`{flag}`: {MCP_USAGE}")),
            file if a.file.is_none() => a.file = Some(file.to_string()),
            _ => return Err(MCP_USAGE.into()),
        }
    }
    if a.connect.is_some() && a.file.is_some() {
        return Err(format!("a window has its own project: --connect takes no FILE ({MCP_USAGE})"));
    }
    Ok(a)
}

/// The MCP server `args` asks for: attached to a window, or on a session of its own with its file open, and read-only when asked.
fn mcp_server(args: McpArgs) -> Result<mcp::Server, String> {
    let mut server = match args.connect {
        Some(port) => mcp::Server::attached(window::Window::connect(port)?),
        None => mcp::Server::new(),
    };
    if let Some(file) = &args.file {
        server.open(file)?;
    }
    if args.read_only {
        server.read_only();
    }
    Ok(server)
}

/// The DWG reader a session is given: `bimcraft-dwg`'s, which reads a drawing in a child process of this program, behind the
/// `dwg` feature. A build without it hands none, and a DWG says to save it as DXF.
#[cfg(feature = "dwg")]
fn dwg_reader() -> Option<DwgReader> {
    bimcraft_dwg::reader()
}

#[cfg(not(feature = "dwg"))]
fn dwg_reader() -> Option<DwgReader> {
    None
}

/// What this program does when it's started as the child that reads a DWG (`bimcraft_dwg::CHILD_ARG`): none when it isn't.
#[cfg(feature = "dwg")]
fn dwg_child(args: &[String]) -> Option<ExitCode> {
    bimcraft_dwg::child_main(args)
}

#[cfg(not(feature = "dwg"))]
fn dwg_child(_: &[String]) -> Option<ExitCode> {
    None
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if let Some(code) = dwg_child(&args) {
        return code;
    }
    if args.first().is_some_and(|a| a == "mcp") {
        let mut server = match mcp_args(&args[1..]).and_then(mcp_server) {
            Ok(server) => server,
            Err(e) => {
                eprintln!("bimcraft-cli mcp: {e}");
                return ExitCode::FAILURE;
            }
        };
        return match server.serve(std::io::stdin().lock(), std::io::stdout().lock()) {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => {
                eprintln!("bimcraft-cli mcp: {e}");
                ExitCode::FAILURE
            }
        };
    }
    match cli(&args, &mut std::io::stdout().lock()) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("{e}");
            ExitCode::FAILURE
        }
    }
}

