21: fn template(lang: &str) -> &'static str {
22:     use crate::templates as t;
23:     match lang {
24:         "pt" => t::PT,
25:         "es" => t::ES,
26:         "sv" => t::SV,
27:         "cs" => t::CS,
28:         "fr" => t::FR,
