36: /// Replaces the `@G<n>` placeholders of a template with GUIDs made now, the same n the same GUID.
37: fn fill_guids(v: &mut Value, made: &mut Vec<Option<String>>) {
38:     match v {
39:         Value::Str(s) => {
40:             if let Some(n) = s.strip_prefix("@G") {
41:                 if let Ok(n) = n.parse::<usize>() {
42:                     if made.len() <= n {
43:                         made.resize(n + 1, None);
44:                     }
45:                     if made[n].is_none() {
46:                         made[n] = Some(crate::rand::guid());
47:                     }
48:                     *s = made[n].clone().unwrap();
49:                 }
50:             }
51:         }
52:         Value::Arr(a) => a.iter_mut().for_each(|x| fill_guids(x, made)),
53:         Value::Obj(m) => m.items.iter_mut().for_each(|(_, x)| fill_guids(x, made)),
54:         _ => {}
55:     }
56: }
