72:     pub fn from_value(v: Value) -> Project {
73:         let mut doc = match v {
74:             Value::Obj(m) => m,
75:             _ => Map::new(),
76:         };
77:         let mut elements = BTreeMap::new();
78:         let mut library = BTreeMap::new();
79:         if let Some(Value::Obj(m)) = doc.get_mut("elements").map(std::mem::take) {
80:             for (k, e) in m.items {
81:                 if let Ok(id) = k.parse::<u64>() {
82:                     elements.insert(id, e);
83:                 }
84:             }
85:         }
86:         if let Some(Value::Obj(m)) = doc.get_mut("library").map(std::mem::take) {
87:             for (k, e) in m.items {
88:                 if let Ok(id) = k.parse::<u64>() {
89:                     library.insert(id, e);
90:                 }
91:             }
92:         }
93:         if !doc.contains("elements") {
94:             doc.insert("elements", Value::Null);
95:         }
96:         if !doc.contains("library") {
97:             doc.insert("library", Value::Null);
98:         }
99:         Project { doc, elements, library, lib_low: 1_000_000 }
100:     }
101: 
102:     pub fn to_value(&self) -> Value {
103:         let mut out = Map::new();
104:         for (k, v) in &self.doc.items {
105:             if k == "elements" {
106:                 let mut m = Map::new();
107:                 for (id, e) in &self.elements {
108:                     m.items.push((id.to_string(), e.clone()));
109:                 }
110:                 out.items.push((k.clone(), Value::Obj(m)));
111:             } else if k == "library" {
112:                 let mut m = Map::new();
113:                 for (id, e) in &self.library {
114:                     m.items.push((id.to_string(), e.clone()));
115:                 }
116:                 out.items.push((k.clone(), Value::Obj(m)));
117:             } else {
118:                 out.items.push((k.clone(), v.clone()));
119:             }
120:         }
121:         Value::Obj(out)
122:     }
