190:             low = low.min(*k);
191:         }
192:         fn scan(v: &Value, low: &mut u64) {
193:             match v {
194:                 Value::Obj(m) => {
195:                     if let Some(Value::Num(n)) = m.get("id") {
196:                         let x = n.as_f64();
