thread_local! {
    /// Set by a command that makes an undo step even where the model is as it was.
    static STEP: Cell<bool> = const { Cell::new(false) };
}

/// A command says it makes an undo step whether or not it changed the model (the original's
/// edits of a named style always do).
pub fn mark_step() {
    STEP.with(|s| s.set(true));
}

/// Whether the command just run makes an undo step though the model is as it was.
pub fn step_anyway(cid: &str) -> bool {
    owns(cid) && STEP.with(|s| s.get())
}

pub const COMMANDS: &[&str] = &[
    "line_pattern",
    "line_style",
    "fill_pattern",
    "import_fill_patterns",
    "export_fill_patterns",
    "filled_region_type",
    "text_type",
    "dimension_type",
    "line_weights",
    "object_styles",
    "units",
    "room_area",
    "language",
    "standard",
    "phase",
    "phase_filter",
    "option",
    "parameter",
    "voltage",
    "distribution_system",
    "wire_type",
    "reinforcement_preset",
];

pub fn owns(cid: &str) -> bool {
    COMMANDS.contains(&cid)
}

/// The longest error the original gives whole; past it, the rest is counted.
const MAX_ERROR: usize = 2000;

/// Marks an error the original's model check gives (after the command), which isn't clipped.
const CHECK: char = '\u{1}';

/// An error as the original's model check gives it after the command: said whole.
pub fn check_error(e: String) -> String {
    format!("{}{}", CHECK, e)
}

/// A command's error past 2000 characters: its first 2000 and how many more there were (what the
/// model's check finds is said whole).
fn clip_error(e: String) -> String {
    if let Some(rest) = e.strip_prefix(CHECK) {
        return rest.to_string();
    }
    let n = e.chars().count();
    if n <= MAX_ERROR {
        return e;
    }
    let mut out: String = e.chars().take(MAX_ERROR).collect();
    out.push_str(&format!("… ({} more characters)", n - MAX_ERROR));
    out
}

/// Runs the commands this module owns; None for the others.
pub fn dispatch(s: &mut Session, cid: &str, p: &Value) -> Option<Result<Value, String>> {
    if !owns(cid) {
        return None;
    }
    STEP.with(|st| st.set(false));
    Some(run(s, cid, p).map_err(clip_error))
}

fn run(s: &mut Session, cid: &str, p: &Value) -> Result<Value, String> {
    match cid {
        "line_pattern" | "line_style" => lines::run(s, cid, p),
        "fill_pattern" | "import_fill_patterns" | "export_fill_patterns" | "filled_region_type" => fills::run(s, cid, p),
        "text_type" | "dimension_type" => text::run(s, cid, p),
        "line_weights" | "object_styles" => weights::run(s, cid, p),
        "units" | "room_area" | "language" | "standard" => settings::run(s, cid, p),
        "phase" | "phase_filter" | "option" => phasing::run(s, cid, p),
        "parameter" => parameters::run(s, cid, p),
        "voltage" | "distribution_system" | "wire_type" => electrical::run(s, cid, p),
        "reinforcement_preset" => presets::run(s, cid, p),
        _ => Err(format!("{}: not supported here", cid)),
    }
}

/// The model rules this module owns, checked after every command.
pub fn check(pr: &crate::project::Project) -> Result<(), String> {
    // presets, electrical settings and project parameters; then phasing's rules, which go through
    // each element's params once, in order, the project parameters' values among them; then the
    // library's names
    parameters::check_project(pr)?;
    let params = common::section(pr, "parameters");
    phasing::check_with(pr, &|_, e, k, v| parameters::check_value(pr, &params, e, k, v))?;
    common::check_library_names(pr)?;
    parameters::check_names(pr)
}

/// What `inspect` says of the sections this module keeps: (key, value) pairs, for the core's
/// `inspect` to merge into its reply (which it prints sorted).
pub fn inspect_entries(s: &Session) -> Vec<(String, Value)> {
    let mut out = Vec::new();
    settings::inspect_entries(s, &mut out);
    phasing::inspect_entries(s, &mut out);
    parameters::inspect_entries(s, &mut out);
    electrical::inspect_entries(s, &mut out);
    out
}

     1	//! Taking a picture into a project: a PNG or a JPEG read, laid over white, halved until no side
     2	//! passes 1024 px, and kept as the PNG `png::encode` writes, named `img-` and its FNV-1a hash.
     3	
     4	use super::png::{self, Image};
     5	
     6	/// The most pixels a picture may have before it's halved.
     7	pub const MAX_PIXELS: u64 = 16_000_000;
     8	/// The longest side a picture is kept with.
     9	pub const MAX_SIDE: u32 = 1024;
    10	/// The most pictures a project holds.
    11	pub const MAX_PICTURES: usize = 24;
    12	
    13	/// A picture as a project keeps it.
    14	pub struct Picture {
    15	    pub id: String,
    16	    pub name: String,
    17	    pub png: Vec<u8>,
    18	    pub w: u32,
    19	    pub h: u32,
    20	}
    21	
    22	/// Why a picture couldn't be taken: a message, or the panic the original would have had.
    23	pub enum Fail {
    24	    Msg(String),
    25	    Panic { at: &'static str, msg: String },
    26	}
    27	
    28	/// The name a picture takes from its file: the file's stem, as Rust's `Path::file_stem` has it.
    29	pub fn stem(path: &str) -> String {
    30	    std::path::Path::new(path).file_stem().map(|s| s.to_string_lossy().to_string()).unwrap_or_default()
    31	}
    32	
    33	/// Reads a picture file and makes the picture a project keeps (`path:` leads every message).
    34	pub fn load(path: &str) -> Result<Picture, Fail> {
    35	    let bytes = match std::fs::read(path) {
    36	        Ok(b) => b,
    37	        Err(e) => return Err(Fail::Msg(format!("{}: {}", path, crate::commands::io_err(&e)))),
    38	    };
    39	    let img = decode_any(&bytes).map_err(|f| match f {
    40	        Fail::Msg(m) => Fail::Msg(format!("{}: {}", path, m)),
    41	        p => p,
    42	    })?;
    43	    Ok(keep(img, &stem(path)))
    44	}
    45	
    46	/// A PNG or a JPEG, by its first bytes, to 8-bit RGBA.
    47	pub fn decode_any(bytes: &[u8]) -> Result<Image, Fail> {
    48	    if bytes.len() >= 8 && &bytes[..8] == b"\x89PNG\r\n\x1a\n" {
    49	        if bytes.len() < 24 {
    50	            return Err(Fail::Msg("it's cut short".into()));
    51	        }
    52	        let w = u32::from_be_bytes(bytes[16..20].try_into().unwrap());
    53	        let h = u32::from_be_bytes(bytes[20..24].try_into().unwrap());
    54	        check_size(w, h)?;
    55	        return match png::decode(bytes) {
    56	            Ok(i) => Ok(i),
    57	            Err(png::Fail::Error(e)) => Err(Fail::Msg(format!("it isn't a PNG BIMCraft can read: {}", e))),
    58	            Err(png::Fail::Panic { at, msg }) => Err(Fail::Panic { at, msg }),
    59	        };
    60	    }
    61	    if bytes.len() >= 3 && bytes[..3] == [0xff, 0xd8, 0xff] {
    62	        return match super::jpeg::decode(bytes) {
    63	            Ok(i) => Ok(i),
    64	            Err(super::jpeg::Fail::Size(w, h)) => {
    65	                check_size(w, h)?;
    66	                Err(Fail::Msg(format!("it's {} by {} px; a picture has up to {} pixels", w, h, MAX_PIXELS)))
    67	            }
    68	            Err(super::jpeg::Fail::Error(e)) => Err(Fail::Msg(format!("it isn't a JPEG BIMCraft can read: {}", e))),
    69	        };
    70	    }
    71	    Err(Fail::Msg("it's neither a PNG nor a JPEG".into()))
    72	}
    73	
    74	pub fn check_size(w: u32, h: u32) -> Result<(), Fail> {
    75	    if w == 0 || h == 0 || w as u64 * h as u64 > MAX_PIXELS {
    76	        return Err(Fail::Msg(format!("it's {} by {} px; a picture has up to {} pixels", w, h, MAX_PIXELS)));
    77	    }
    78	    Ok(())
    79	}
    80	
    81	/// Lays the picture over white, halves it until it fits, and keeps it as a PNG.
    82	pub fn keep(mut img: Image, name: &str) -> Picture {
    83	    flatten(&mut img);
    84	    while img.w > MAX_SIDE || img.h > MAX_SIDE {
    85	        img = halve(&img);
    86	    }
    87	    let png = png::encode(&img);
    88	    let id = format!("img-{:016x}", crate::util::fnv1a64(&png));
    89	    Picture { id, name: name.to_string(), png, w: img.w, h: img.h }
    90	}
    91	
    92	/// Over white: each colour weighted by its alpha, rounded; alpha made opaque.
    93	fn flatten(img: &mut Image) {
    94	    for p in img.rgba.chunks_exact_mut(4) {
    95	        let a = p[3] as u32;
    96	        if a == 255 {
    97	            continue;
    98	        }
    99	        for c in p.iter_mut().take(3) {
   100	            *c = ((*c as u32 * a + 255 * (255 - a) + 127) / 255) as u8;
   101	        }
   102	        p[3] = 255;
   103	    }
   104	}
   105	
   106	/// Half the size (at least 1 px a side), each pixel the rounded mean of the 2 by 2 it covers
   107	/// (the last row or column standing in for one that's missing).
   108	fn halve(img: &Image) -> Image {
   109	    let (w, h) = (img.w as usize, img.h as usize);
   110	    let (nw, nh) = ((w / 2).max(1), (h / 2).max(1));
   111	    let mut out = vec![0u8; nw * nh * 4];
   112	    for y in 0..nh {
   113	        let y0 = (2 * y).min(h - 1);
   114	        let y1 = (2 * y + 1).min(h - 1);
   115	        for x in 0..nw {
   116	            let x0 = (2 * x).min(w - 1);
   117	            let x1 = (2 * x + 1).min(w - 1);
   118	            for c in 0..4 {
   119	                let s = img.rgba[(y0 * w + x0) * 4 + c] as u32
   120	                    + img.rgba[(y0 * w + x1) * 4 + c] as u32
   121	                    + img.rgba[(y1 * w + x0) * 4 + c] as u32
   122	                    + img.rgba[(y1 * w + x1) * 4 + c] as u32;
   123	                out[(y * nw + x) * 4 + c] = ((s + 2) / 4) as u8;
   124	            }
   125	        }
   126	    }
   127	    Image { w: nw as u32, h: nh as u32, rgba: out }
   128	}
   129	
   130	/// What the original prints when its PNG reader panics, and the error the command gives then.
   131	pub fn panic_error(cmd: &str, at: &str, msg: &str) -> String {
   132	    eprintln!(
   133	        "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
   134	        std::process::id(),
   135	        at,
   136	        msg
   137	    );
   138	    format!("internal error in `{}`: {}", cmd, msg)
   139	}
