   428	    }
   429	    let mut v = Vec::new();
   430	    for &(x0, y0, dx, dy) in &ADAM7 {
   431	        let w = if hdr.w > x0 { (hdr.w - x0 + dx - 1) / dx } else { 0 };
   432	        let h = if hdr.h > y0 { (hdr.h - y0 + dy - 1) / dy } else { 0 };
   433	        if w > 0 && h > 0 {
   434	            v.push(Pass { x0, y0, dx, dy, w, h });
   435	        }
   436	    }
   437	    v
   438	}
