use super::deflate::{self, Error as InflateError};

/// A stored page: 65,249 bytes, of which the first 64,896 are data.
pub const PAGE: usize = 65_249;
pub const PAGE_DATA: usize = 64_896;
/// What one stream may inflate to.
pub const INFLATE_CAP: usize = 512 << 20;
/// A single-member stream has its member within its first 256 bytes.
pub const HEAD_WINDOW: usize = 256;

/// Whether the container stores the stream in pages.
pub fn is_paged(name: &str) -> bool {
    name.starts_with("Partitions/")
        || matches!(
            name,
            "Formats/Latest"
                | "Global/ContentDocuments"
                | "Global/DocumentIncrementTable"
                | "Global/ElemTable"
                | "Global/History"
                | "Global/Latest"
                | "Global/PartitionTable"
        )
}

/// The stream with the run at the end of each whole page taken out (a short last page is kept whole).
pub fn strip_pages(data: &[u8]) -> Vec<u8> {
    if data.len() < PAGE {
        return data.to_vec();
    }
    let mut out = Vec::with_capacity(data.len());
    let mut i = 0;
    while i < data.len() {
        if i + PAGE <= data.len() {
            out.extend_from_slice(&data[i..i + PAGE_DATA]);
        } else {
            out.extend_from_slice(&data[i..]);
        }
        i += PAGE;
    }
    out
}

fn find_magic(data: &[u8], from: usize, limit: usize) -> Option<usize> {
    let end = limit.min(data.len());
    let mut i = from;
    while i + 3 <= data.len() && i < end {
        if data[i] == 0x1f && data[i + 1] == 0x8b && data[i + 2] == 0x08 {
            return Some(i);
        }
        i += 1;
    }
    None
}

/// The offset of the deflate data of the member whose magic is at `m`.
fn parse_header(data: &[u8], m: usize) -> Result<usize, String> {
    let cut = || "the gzip header is cut short".to_string();
    if m + 10 > data.len() {
        return Err(cut());
    }
    let flg = data[m + 3];
    if flg & 0xe0 != 0 {
        return Err(cut());
    }
    let mut p = m + 10;
    if flg & 0x04 != 0 {
        if p + 2 > data.len() {
            return Err(cut());
        }
        let xlen = u16::from_le_bytes([data[p], data[p + 1]]) as usize;
        p += 2;
        if p + xlen > data.len() {
            return Err(cut());
        }
        p += xlen;
    }
    for bit in [0x08u8, 0x10] {
        if flg & bit != 0 {
            match data[p.min(data.len())..].iter().position(|b| *b == 0) {
                Some(z) => p += z + 1,
                None => return Err(cut()),
            }
        }
    }
    if flg & 0x02 != 0 {
        if p + 2 > data.len() {
            return Err(cut());

/// How far into a stream the first member is looked for.
const FIRST_MEMBER_WITHIN: usize = 256;

/// Whether the container stores this stream in pages: the partitions, the schema and the `Global` streams that hold gzip.
///
/// The list is rvt-rs's. The sample bytes confirm it for the five streams that are longer than a page in some sample
/// (`Partitions/NN`, `Formats/Latest`, `Global/ContentDocuments`, `Global/Latest`, and `Global/ElemTable` from 2024, which
/// are cut by the page numbers or do not verify). `Global/DocumentIncrementTable`, `Global/History` and
/// `Global/PartitionTable` are under 18 KB in all four, so stripping them removes nothing and the samples cannot say whether
/// a longer one would be paged; neither can they say it of `Contents`, `BasicFileInfo`, `TransmissionData` and
/// `ProjectInformation`, which are under 4.1 KB and not listed.
pub fn is_paged(stream: &str) -> bool {
    if let Some(rest) = stream.strip_prefix("Partitions/") {
        return !rest.is_empty() && !rest.contains('/');
    }
    matches!(
        stream,
        "Formats/Latest"
            | "Global/ContentDocuments"
            | "Global/DocumentIncrementTable"
            | "Global/ElemTable"
            | "Global/History"
            | "Global/Latest"
            | "Global/PartitionTable"
    )
}

/// Removes each full page's trailer, in place. A last page shorter than a full one is kept whole. No sample ends inside the
/// last 352 bytes of a page, where a stream that was cut off would keep part of a run; a writer that finishes its runs
/// cannot leave one, so this is a choice about damaged files and not an observation.
pub fn strip_pages(mut data: Vec<u8>) -> Vec<u8> {
    let full = data.len() / PAGE_STORED;
    for page in 1..full {
        let from = page * PAGE_STORED;
        data.copy_within(from..from + PAGE_PAYLOAD, page * PAGE_PAYLOAD);
    }
    if full > 0 {
        let tail = full * PAGE_STORED;
        let kept = data.len() - tail;
        data.copy_within(tail.., full * PAGE_PAYLOAD);
        data.truncate(full * PAGE_PAYLOAD + kept);
    }
    data
}

